let rtxSyncBusy=false,rtxLastSync=0;async function syncOnStartup(){if(!cloud?.token||rtxSyncBusy)return;rtxSyncBusy=true;try{let rows=await api('/rest/v1/road_to_x_sync?select=payload&user_id=eq.'+encodeURIComponent(cloud.user_id),'GET',null,cloud.token);if(rows?.[0]?.payload){const local=clone(data),remote=migratePayload(rows[0].payload);data={...clone(DEFAULT),...mergeData(remote,local)};migrateV13();localStorage.setItem('road_to_x_data',JSON.stringify(data));render();await pushCloud()}else await pushCloud();status('● Synchronisé')}catch(e){status('● Synchronisation à vérifier')}finally{rtxSyncBusy=false;rtxLastSync=Date.now()}}
window.addEventListener('focus',()=>{if(cloud?.token&&Date.now()-rtxLastSync>60000)syncOnStartup()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&cloud?.token&&Date.now()-rtxLastSync>60000)syncOnStartup()});

