// --- V13.1 : rangs personnels visibles et cohérents sur chaque rubrique ---
function latestFoodRankV131(){
  const rows=Object.entries(data.food_daily||{}).filter(([,v])=>v&&v.logged).sort(([a],[b])=>a.localeCompare(b));
  if(!rows.length)return null;
  const [day,row]=rows[rows.length-1];
  return {day,score:foodScore(day),rank:rankFromScore(foodScore(day)),row};
}
function rankBoxV131(label,rank,score,sub=''){
  const color=rank==='À RENSEIGNER'?'#91a1c1':rankColor(rank);
  return `<div class="personal-rank-box"><span>${label}</span><b style="color:${color}">${safe(rank)}</b><small>${score===null?'À renseigner':`${Number(score).toFixed(0)} / 100`}${sub?` · ${safe(sub)}`:''}</small></div>`;
}
function renderRanksV131(){
  const p=$('#page'),m=rankMetrics(),h=humanScores(),food=latestFoodRankV131();
  const work=[['ratio','Ratio de travail'],['objectifs','Progression des objectifs'],['sujets','Progression des sujets'],['notes','Notes'],['classements','Classements']];
  const criteria=work.map(([k,label])=>{let x=m[k];return `<div class="item rank-criterion"><div class="row"><strong>${label}</strong><b style="color:${rankColor(x.rank)}">${x.rank}</b></div><small>${Number(x.score).toFixed(1)} / 100</small><div class="progress"><i style="width:${Math.max(0,Math.min(100,x.score))}%;background:${pctColor(x.score)}"></i></div></div>`}).join('');
  const foodSub=food&&food.day!==dateISO()?`saisie ${fmtDate(food.day)}`:'';
  p.innerHTML=`<h2 class="page-title">Rangs</h2><p class="page-sub">Rang général = moyenne des cinq critères de travail. Les rangs personnels sont distincts.</p>${card('Rang général du jour',`<div class="rank-general-v131"><b style="color:${rankColor(m.final.rank)}">${m.final.rank}</b><span>${m.final.score.toFixed(1)} / 100</span></div><small class="muted">Moyenne des cinq rangs de travail</small>`)}${card('Rangs personnels',`<div class="personal-ranks-grid">${rankBoxV131('RANG HUMAIN',h.human_rank,h.human)}${rankBoxV131('RANG ALIMENTAIRE',food?.rank||'À RENSEIGNER',food?.score??null,foodSub)}${rankBoxV131('RANG DÎN',h.deen_rank,h.deen)}</div>`)}${card('Les cinq critères de travail',criteria)}`;
}
function renderHygieneV131(){
  const p=$('#page'),today=dateISO(),rec=data.hygiene_daily?.[today]||{teeth:0},n=Math.max(0,Math.min(3,num(rec.teeth))),tooth=['#ff2525','#f97316','#f5d90a','#48c6a0'][n],h=humanScores(),food=latestFoodRankV131();
  const hist=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-i);let k=dateISO(d),v=data.hygiene_daily?.[k]||{},count=Math.max(0,Math.min(3,num(v.teeth)));return `<div class="item row"><span>${fmtDate(k)}</span><b style="color:${['#ff2525','#f97316','#f5d90a','#48c6a0'][count]}">${count}/3</b></div>`}).join('');
  const foodSub=food&&food.day!==today?`dernière saisie ${fmtDate(food.day)}`:'';
  const f=food?.row;
  const summary=f?`Fruits ${num(f.fruit)} portions · Légumes ${num(f.vegetables)} portions · Eau ${num(f.water_l)} L · Bonbons ${num(f.candy)} · Chocolat ${num(f.chocolate_g)} g · Biscuits ${num(f.biscuits)} · Fast-food ${num(f.fast_food)}`:'Aucune saisie alimentaire pour le moment.';
  p.innerHTML=`<h2 class="page-title">Hygiène de vie</h2><p class="page-sub">Habitudes quotidiennes, alimentation et rang humain.</p>${card('Rangs personnels',`<div class="personal-ranks-grid">${rankBoxV131('RANG HUMAIN',h.human_rank,h.human)}${rankBoxV131('RANG ALIMENTAIRE',food?.rank||'À RENSEIGNER',food?.score??null,foodSub)}</div>`)}${card('Brossage des dents',`<div class="row"><strong style="font-size:25px;color:${tooth}">${n} / 3</strong><div>${btn('+','teeth-plus')} ${btn('−','teeth-minus')}</div></div>`)}${card('Historique · 7 jours',hist)}${card('Journal alimentaire',`<p class="tiny muted">${safe(summary)}</p><p class="tiny muted">Fruits, légumes et eau améliorent le score ; les quantités de produits sucrés et de fast-food le réduisent. Indicateur personnel, pas une évaluation médicale.</p>`,btn('Ouvrir le journal alimentaire','food-journal','primary full'))}`;
}
function renderDeenV131(){
  const p=$('#page'),today=dateISO(),rec=data.deen_daily?.[today]||{},h=humanScores(),prayers=['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  const history=(data.human_rank_history||[]).slice(-7).reverse().map(x=>{let score=num(x.deen),rank=x.deen_rank||rankFromScore(score);return `<div class="item row"><span>${fmtDate(x.date)}</span><b style="color:${rankColor(rank)}">${rank} · ${score.toFixed(0)}/100</b></div>`}).join('')||empty('L’historique apparaîtra après tes premières saisies.');
  p.innerHTML=`<h2 class="page-title">Dîn</h2><p class="page-sub">Suivi quotidien personnel.</p>${card('Rang Dîn du jour',`<div class="rank-general-v131"><b style="color:${rankColor(h.deen_rank)}">${h.deen_rank}</b><span>${h.deen.toFixed(0)} / 100</span></div>`)}${card('Prières',prayers.map(k=>`<label class="check-row"><input type="checkbox" data-prayer="${k}" ${rec[k]?'checked':''}> ${k}</label>`).join(''))}${card('Lecture du Coran',`<div class="row"><strong>${num(rec.quran_minutes)} min aujourd’hui</strong><div>${btn('+ 10 min','quran-plus')} ${btn('− 10 min','quran-minus')}</div></div>`)}${card('Historique du rang Dîn · 7 jours',history)}`;
}
const _rtxRenderV131Base=render;
render=function(){
  _rtxRenderV131Base();
  if(page==='ranks')renderRanksV131();
  else if(page==='hygiene')renderHygieneV131();
  else if(page==='deen')renderDeenV131();
};

render();if(cloud?.token)syncOnStartup();
